def f(N: int, edges: List[Tuple[int, int, int]], Q: int, K: int, queries: List[Tuple[int, int]]) -> int:
    '''
    N: an integer
    edges: a list of tuples, each containing three integers
    Q: an integer
    K: an integer
    queries: a list of tuples, each containing two integers
    '''
    graph = [[] for _ in range(N+1)]
    for a, b, c in edges:
        graph[a].append((b, c))
        graph[b].append((a, c))
    result = []
    for x, y in queries:
        if x == K or y == K:
            result.append(0)
        else:
            max_c = 0
            for b, c in graph[x]:
                if b == y:
                    max_c = max(max_c, c)
            for a, c in graph[y]:
                if a == x:
                    max_c = max(max_c, c)
            result.append(max_c)
    return result
```

